// Only genuine, recent FormCraft requests get past this step.
const item = $input.first().json;
const header = String(item.headers['x-formcraft-signature'] || '');
const parts = Object.fromEntries(header.split(',').map((p) => [p.slice(0, p.indexOf('=')), p.slice(p.indexOf('=') + 1)]));
const ageSeconds = Math.abs(Date.now() / 1000 - Number(parts.t));
if (!parts.v1 || parts.v1 !== item.expectedSignature || !(ageSeconds <= 300)) {
  throw new Error('Not a genuine FormCraft request: check the signing secret in the previous step.');
}
// The event: eventType is response.completed, or response.partial_saved,
// response.abandoned or response.resumed if you chose those in FormCraft.
return [{ json: item.body }];
